import java.util.List;

public class Main {
    record Question(String prompt, String answer) { }
    public static void main(String[] args) {
        List<Question> quiz = List.of(
            new Question("What keyword creates a subclass?", "extends"),
            new Question("Which type stores true or false?", "boolean"));
        List<String> submitted = List.of("extends", "boolean");
        int score = 0;
        for (int i = 0; i < quiz.size(); i++) {
            boolean correct = quiz.get(i).answer().equalsIgnoreCase(submitted.get(i));
            if (correct) score++;
            System.out.println((i + 1) + ": " + (correct ? "correct" : "review"));
        }
        System.out.println("Score: " + score + "/" + quiz.size());
    }
}
